import { chromium } from 'playwright';

const url = 'http://localhost:4173/';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1000, height: 700 } });
await page.goto(url, { waitUntil: 'networkidle' });
await page.screenshot({ path: '/tmp/shot/light.png' });

// switch to dark theme
await page.getByText('Тёмная', { exact: true }).click();
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/shot/dark.png' });

// hover mid-chart to check tooltip/crosshair in dark
const box = await page.locator('.themed-line-chart__svg').boundingBox();
await page.mouse.move(box.x + box.width * 0.55, box.y + box.height * 0.5);
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/shot/dark-hover.png' });

await browser.close();
console.log('done');

